export interface MatcherOptions {
  jwtSecret?: string
  jwtRoleClaim?: string
  allowMidSegmentCaptures?: boolean
}

type HeaderValue = string | readonly string[] | undefined
type CookieValue = string | undefined

/** A plain object, or an iterable of `[name, value]` pairs such as `Headers` or `Map`. */
export type FieldRecord<V> = Readonly<Record<string, V>> | Iterable<readonly [string, V]>

export interface MatchRequest {
  scheme: string
  host: string
  /** Already URL-decoded. */
  path: string
  /** Without the leading `?`. */
  query: string
  /** Names are matched case-insensitively; an array matches on its first value. */
  headers?: FieldRecord<HeaderValue>
  cookies?: FieldRecord<CookieValue>
}

export interface Signer {
  secret: string
  /** Name of the environment variable holding the signing secret. */
  jwtSecret: string
  type: string
  header: string
  expiresIn: number
  extraFields: Record<string, unknown>
}

export type MatchResult =
  | {
      type: 'match'
      status: number
      to: string
      force: boolean
      proxyHeaders: Record<string, string>
      signer?: Signer
      netlifyVary: string
    }
  | { type: 'forcedNotFound'; netlifyVary: string }

export interface ParseError {
  readonly message: string
}

export interface Matcher {
  /** Returns null when no rule matched and none forced a 404. */
  match(req: MatchRequest): MatchResult | null
  readonly parseErrors: readonly ParseError[]
  readonly rulesCount: number
  /** Frees the matcher. Calling match afterwards throws. */
  close(): void
}

/**
 * Builds a matcher from rules in the JSON shape produced by
 * `@netlify/redirect-parser`. Invalid rules are skipped and reported in
 * `parseErrors` rather than rejecting.
 */
export function createMatcher(rules: string | readonly object[], options?: MatcherOptions): Promise<Matcher>
